        BigDecimal dueTotal = NONE;
        for (Person person : sheetPeople) {
            Figures f = figuresOf(sheetId, today, person, counted.getOrDefault(person.getId(), List.of()));
            figures.put(person.getId(), f);
            claimedTotal = claimedTotal.add(f.claimed());
            if (f.due() != null) {
                dueTotal = dueTotal.add(f.due());
            }
        }
        return new Rollup(figures, claimedTotal, dueTotal);
    }

    /** A person's figures from their claims that count: the sum of their amounts, and the sum of the
     *  figures they show, or none when the grade has no rate in force on the sheet's today and no
     *  settled or stated claim of theirs keeps a figure. */
    private Figures figuresOf(String sheetId, LocalDate today, Person person, List<Claim> counted) {
        BigDecimal claimed = NONE;
        BigDecimal due = NONE;
        boolean anyFigure = false;
        for (Claim claim : counted) {
            claimed = claimed.add(claim.getAmount());
            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
            if (figure != null) {
                due = due.add(figure);
            }
            anyFigure |= claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
        }
        boolean hasRate = rates.rateOn(sheetId, person.getGrade(), today).isPresent();
        return new Figures(person.getName(), claimed, hasRate || anyFigure ? due : null);
    }

    private static String text(BigDecimal due) {
        return due == null ? NO_RATE : due.toPlainString();
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, identified by the id a user types. Everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    /** The sheet's today: every date-dependent decision and default date on the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number given on the sheet; the next claim opened takes the one after. */
    @Column(name = "last_claim_number", nullable = false)
    private long lastClaimNumber;

    /** The clerk limit: a clerk settles a claim only when its due is at or below it; null for none. */
    @Column(name = "clerk_limit")
    private BigDecimal clerkLimit;

    /** The floor: a claim's live due is at least it. */
    @Column(name = "due_floor", nullable = false)
    private BigDecimal floor = new BigDecimal("1.00");

    protected Sheet() {
    }

    public Sheet(String id, LocalDate today) {
        this.id = id;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    /** Take the sheet's next claim number. */
    public long nextClaimNumber() {
        return ++lastClaimNumber;
    }
}
